# coding: utf-8
"""
SERVIDOR DE RASTREIO E LANDING PAGE OFICIAL DO TORCEDOR — SPFC TICKET 2026 (RENDER)
"""

import os
import re
import json
import base64
from flask import Flask, request, jsonify, render_template_string, send_file, Response

app = Flask(__name__)

DB_FILE = "pedidos_render.json"
SYNC_SECRET = os.environ.get("SYNC_SECRET", "spfc2026_segredo_sync")

MORUMBI_B64 = """"""

@app.route('/morumbi_festa_noite.jpg')
def morumbi_imagem():
    caminho = os.path.join(os.path.dirname(__file__), 'morumbi_festa_noite.jpg')
    if os.path.exists(caminho):
        return send_file(caminho, mimetype='image/jpeg', max_age=31536000)
    return Response(
        base64.b64decode(MORUMBI_B64),
        mimetype='image/jpeg',
        headers={'Cache-Control': 'public, max-age=31536000'}
    )

def limpar_cpf(c):
    return re.sub(r'\D', '', str(c or ''))

def carregar_pedidos():
    if os.path.exists(DB_FILE):
        try:
            with open(DB_FILE, 'r', encoding='utf-8') as f:
                return json.load(f)
        except Exception:
            pass
    return {}

def salvar_pedidos(dados):
    try:
        with open(DB_FILE, 'w', encoding='utf-8') as f:
            json.dump(dados, f, ensure_ascii=False, indent=2)
    except Exception as e:
        print(f"[RENDER DB ERROR] {e}")

