@app.route('/')
@app.route('/pedido')
@app.route('/pedido/<cpf>')
@app.route('/rastreio')
@app.route('/rastreio/<cpf>')
@app.route('/acompanhar')
@app.route('/acompanhar/<cpf>')
@app.route('/ingresso')
@app.route('/ingresso/<cpf>')
def rota_rastreio_pagina(cpf=None):
    return render_template_string(HTML_RASTREIO)

@app.route('/api/rastreio', methods=['GET'])
def api_rastreio():
    cpf = request.args.get('cpf', '')
    cpf_limpo = limpar_cpf(cpf)
    if not cpf_limpo or len(cpf_limpo) != 11:
        return jsonify({"encontrado": False, "mensagem": "CPF inválido"}), 400

    pedidos = carregar_pedidos()
    if cpf_limpo in pedidos:
        return jsonify({"encontrado": True, "pedido": pedidos[cpf_limpo]})
    return jsonify({"encontrado": False})

@app.route('/api/sincronizar', methods=['POST'])
def api_sincronizar():
    auth = request.headers.get("Authorization", "")
    token = auth.replace("Bearer ", "").strip()
    if token != SYNC_SECRET:
        return jsonify({"sucesso": False, "erro": "Não autorizado"}), 401

    payload = request.get_json(force=True, silent=True)
    if not payload:
        return jsonify({"sucesso": False, "erro": "Payload vazio"}), 400

    cpf_limpo = limpar_cpf(payload.get("cpf"))
    if not cpf_limpo or len(cpf_limpo) != 11:
        return jsonify({"sucesso": False, "erro": "CPF ausente ou inválido"}), 400

    pedidos = carregar_pedidos()

    if payload.get("remover") is True:
        if cpf_limpo in pedidos:
            del pedidos[cpf_limpo]
            salvar_pedidos(pedidos)
        return jsonify({"sucesso": True, "mensagem": "Pedido removido com sucesso!"})

    pedidos[cpf_limpo] = {
        "cpf": cpf_limpo,
        "status": payload.get("status", "CONCLUIDO"),
        "setor_comprado": payload.get("setor_comprado", "Arquibancada"),
        "id_pedido": str(payload.get("id_pedido", "SPFC-OK")),
        "data_hora": str(payload.get("data_hora", "")),
        "setores_solicitados": str(payload.get("setores_solicitados", "")),
        "status_biometria": str(payload.get("status_biometria", "APROVADO"))
    }
    salvar_pedidos(pedidos)
    return jsonify({"sucesso": True, "mensagem": "Pedido sincronizado com sucesso!"})

